import{_ as a,o,c as i,ae as t}from"./chunks/framework.BZib5Ft4.js";const c="/docs/assets/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260511124938_184_76.C7ggb97l.jpg",l="/docs/assets/%E5%BE%AE%E4%BF%A1%E5%9B%BE%E7%89%87_20260511124939_185_76.2SFe__f7.jpg",m=JSON.parse('{"title":"ZR-AI服务接入文档","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),d={name:"index.md"};function r(s,e,n,_,h,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="zr-ai服务接入文档" tabindex="-1">ZR-AI服务接入文档 <a class="header-anchor" href="#zr-ai服务接入文档" aria-label="Permalink to &quot;ZR-AI服务接入文档&quot;">​</a></h1><p>本应用提供统一登录门户、网站级访问控制、三方授权码换取用户身份、用户状态检查、头像和文件上传、投诉建议收集等能力。</p><blockquote><p>本接口文档目前只支持内部使用，后期开放申请。</p></blockquote><h2 id="当前线上地址" tabindex="-1">当前线上地址 <a class="header-anchor" href="#当前线上地址" aria-label="Permalink to &quot;当前线上地址&quot;">​</a></h2><ul><li>门户：<code>https://zrg.zrbyhelp.com/</code></li><li>MinIO：<code>https://minio.zrbyhelp.com</code></li></ul><h2 id="推荐接入流程" tabindex="-1">推荐接入流程 <a class="header-anchor" href="#推荐接入流程" aria-label="Permalink to &quot;推荐接入流程&quot;">​</a></h2><ol><li>管理员在门户后台创建网站服务，填写入口地址、回调地址、健康检查地址和文档地址。</li><li>三方网站在未登录时跳转到门户 <code>/login</code>，携带 <code>client_id</code>、<code>callback</code>、<code>state</code>。</li><li>门户验证用户是否有当前网站权限，通过后回调三方网站并携带一次性 <code>code</code>。</li><li>三方网站服务端用 <code>clientId + clientSecret + code</code> 请求 <code>/api/service-auth/token</code> 换取用户身份。</li><li>三方网站建立自己的本地 session，并定期调用 <code>/api/service-auth/user-status</code> 判断用户是否仍可访问。</li></ol><h2 id="用户体验能力" tabindex="-1">用户体验能力 <a class="header-anchor" href="#用户体验能力" aria-label="Permalink to &quot;用户体验能力&quot;">​</a></h2><ul><li>门户会在三方回调中携带 <code>theme</code> 和 <code>locale</code>，方便三方网站同步日夜模式和语言。</li><li>三方网站可打开 <code>/feedback?service_slug=xxx&amp;embed=1</code> 收集投诉建议。</li><li>三方网站可调用门户的头像、资料和文件上传接口，避免直接暴露对象存储凭据。</li></ul><h2 id="捐赠支持" tabindex="-1">捐赠支持 <a class="header-anchor" href="#捐赠支持" aria-label="Permalink to &quot;捐赠支持&quot;">​</a></h2><p>感谢你的支持，捐赠将用于服务器和服务维护。</p><p><img src="'+c+'" alt="捐赠图片 1"></p><p><img src="'+l+'" alt="捐赠图片 2"></p>',13)])])}const b=a(d,[["render",r]]);export{m as __pageData,b as default};
